      if (lookahead == 'W' ||
          lookahead == 'w') ADVANCE(111);
      if (('0' <= lookahead && lookahead <= '9')) ADVANCE(102);
      if (('B' <= lookahead && lookahead <= '_') ||
          ('b' <= lookahead && lookahead <= 'z')) ADVANCE(120);
      END_STATE();
    case 1:
      if (lookahead == '\n') ADVANCE(37);
      END_STATE();
    case 2:
      if (lookahead == '"') ADVANCE(105);
      if (lookahead != 0 &&
          lookahead != '\n' &&
          lookahead != '\r') ADVANCE(2);
